package com.melonman106.vbvclient;
import java.util.ArrayList;import java.util.Comparator;import java.util.List;import java.util.Locale;
import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.components.EditBox;import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.input.KeyEvent;import net.minecraft.client.input.MouseButtonEvent;import net.minecraft.network.chat.Component;
public final class VBVModsScreen extends Screen{
 private final Screen parent;private final List<VBVModInfo> all=new ArrayList<>();private final List<VBVModInfo> shown=new ArrayList<>();private VBVModInfo selected;private String searchText="";private boolean ascending=true;private int typeFilter=0;private int listScroll=0;private EditBox searchBox;private Button configButton;private int paneWidth;private static final String[] CONFIG_IDS={"simple-hud-enhanced","ukus-armor-hud","custom-crosshair","gamma-utils","zoomify","betterf3","mouse-tweaks","appleskin","vbv-minimap","jade"};
 public VBVModsScreen(Screen p){super(Component.literal("Mods"));parent=p;all.addAll(VBVClient.getMods());}
 private int listBottom(){return height-36;}private int visibleRows(){return Math.max(1,(listBottom()-67-4)/30);}private int maxListScroll(){return Math.max(0,shown.size()-visibleRows());}
 @Override protected void init(){super.init();paneWidth=width/2-8;searchBox=new EditBox(font,20,22,paneWidth-40,20,Component.literal("Search"));searchBox.setValue(searchText);searchBox.setResponder(t->{searchText=t;listScroll=0;refilter();});addRenderableWidget(searchBox);addRenderableWidget(Button.builder(Component.literal(ascending?"Sort A-Z":"Sort Z-A"),b->{ascending=!ascending;b.setMessage(Component.literal(ascending?"Sort A-Z":"Sort Z-A"));refilter();}).bounds(paneWidth-120,45,56,20).build());addRenderableWidget(Button.builder(Component.literal("All"),b->{typeFilter=(typeFilter+1)%3;b.setMessage(Component.literal(typeFilter==0?"All":typeFilter==1?"Native":"Packs"));refilter();}).bounds(paneWidth-60,45,56,20).build());configButton=Button.builder(Component.literal("Config"),b->{if(selected==null)return;openConfig(selected.id());}).bounds(width-56,48,52,20).build();addRenderableWidget(configButton);addRenderableWidget(Button.builder(Component.literal("World Map"),b->VBVNav.open(new VBVWorldMapScreen(this))).bounds(width/2-158,height-28,98,20).build());addRenderableWidget(Button.builder(Component.literal("HUD Editor"),b->VBVNav.open(new VBVHudEditorScreen(this))).bounds(width/2-55,height-28,105,20).build());addRenderableWidget(Button.builder(Component.literal("Done"),b->VBVNav.open(parent)).bounds(width/2+60,height-28,98,20).build());refilter();}
 private void openConfig(String id){if("simple-hud-enhanced".equals(id))VBVNav.open(new VBVSimpleHudConfigScreen(this));else if("ukus-armor-hud".equals(id))VBVNav.open(new VBVArmorHudConfigScreen(this));else if("custom-crosshair".equals(id))VBVNav.open(new VBVCrosshairScreen(this));else if(java.util.Arrays.asList("gamma-utils","zoomify","betterf3","mouse-tweaks","appleskin","vbv-minimap","jade").contains(id))VBVNav.open(new VBVFeatureConfigScreen(this,id,selected.name()));}
 private void refilter(){String q=searchText.trim().toLowerCase(Locale.ROOT);shown.clear();for(VBVModInfo i:all){if(typeFilter==1&&i.resourcePackMod())continue;if(typeFilter==2&&!i.resourcePackMod())continue;if(!q.isEmpty()&&!matches(i,q))continue;shown.add(i);}Comparator<VBVModInfo> c=Comparator.comparing(VBVModInfo::name,String.CASE_INSENSITIVE_ORDER);shown.sort(ascending?c:c.reversed());if(selected==null||!shown.contains(selected))select(shown.isEmpty()?null:shown.get(0));listScroll=Math.max(0,Math.min(listScroll,maxListScroll()));}
 private static boolean matches(VBVModInfo i,String q){return String.valueOf(i.name()).toLowerCase(Locale.ROOT).contains(q)||String.valueOf(i.id()).toLowerCase(Locale.ROOT).contains(q)||String.valueOf(i.description()).toLowerCase(Locale.ROOT).contains(q);}
 private void select(VBVModInfo i){selected=i;if(configButton!=null)configButton.visible=i!=null&&java.util.Arrays.asList(CONFIG_IDS).contains(i.id());}
 private void moveSelection(int d){if(shown.isEmpty())return;int i=selected==null?0:Math.max(0,shown.indexOf(selected));i=Math.max(0,Math.min(shown.size()-1,i+d));select(shown.get(i));if(i<listScroll)listScroll=i;if(i>=listScroll+visibleRows())listScroll=i-visibleRows()+1;}
 @Override public boolean keyPressed(KeyEvent e){if(e.isUp()){moveSelection(-1);return true;}if(e.isDown()){moveSelection(1);return true;}return super.keyPressed(e);}
 @Override public boolean mouseClicked(MouseButtonEvent e,boolean dbl){if(super.mouseClicked(e,dbl))return true;double mx=e.x(),my=e.y();if(mx< paneWidth&&my>=67&&my<listBottom()){int row=(int)((my-67)/30)+listScroll;if(row>=0&&row<shown.size()){select(shown.get(row));if(dbl)VBVNav.open(new VBVModDetailsScreen(this,selected));return true;}}return false;}
 @Override public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float pt){g.fill(0,0,width,height,0xFF101010);super.extractRenderState(g,mx,my,pt);g.text(font,"MODS",paneWidth/2-font.width("MODS")/2,8,0xFFFFFFFF,true);int y=70;for(int i=listScroll;i<shown.size()&&y<listBottom();i++){VBVModInfo m=shown.get(i);if(m==selected)g.fill(6,y-2,paneWidth-6,y+24,0x66336699);g.text(font,m.name(),12,y,0xFFFFFFFF,true);g.text(font,m.version(),12,y+12,0xFF888888,false);y+=30;}if(selected!=null){int x=paneWidth+8;g.text(font,selected.name(),x,82,0xFFFFFFFF,true);g.text(font,"By "+selected.authors(),x,98,0xFFAAAAAA,false);g.text(font,selected.description(),x,120,0xFFD0D0D0,false);}}
 @Override public void onClose(){VBVNav.open(parent);}
}
